      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Identifying existing approaches used to evaluate the sustainability of evidence-based interventions in healthcare",
      "reason": "The title clearly conveys the main objective/review question: identifying approaches to evaluate sustainability of evidence-based interventions in healthcare (population/context and focus are specified)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
