{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The background/abstract describes the current state of knowledge (limited evidence on sustainability evaluation) and uncertainties (unclear which approaches are most effective, disconnect between determinants and outcomes)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "implementation, which often requires substantial resources, is meaningless without long-term sustainability efforts [3]... It is unclear which approach/approaches are most effective for evaluating sustainability and what measures and outcomes are most commonly used.",
      "reason": "The importance and need for the review are explained: sustainability evaluation is essential to implementation science, and the review offers methodological recommendations to advance the field."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The manuscript acknowledges similar prior syntheses (e.g., Lennox et al. [6], a recent scoping review [8]) and explains how the current review differs by focusing on evaluation approaches, timing, methods, measures, and outcomes."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of approaches used to evaluate sustainability of EBIs, not a review of intervention effects, so describing a mechanism of action of an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines evaluation approaches/methods rather than assessing the effects of a specific complex intervention, so a logic model of intervention components and outcomes is not required."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical approach for sustainability ... • Were within a healthcare setting • Evaluated the sustainability of an EBI",
      "reason": "Table 1 specifies study characteristics for eligibility, including study design (primary research with explicit design), healthcare setting (with a detailed definition of healthcare settings), and the requirement of an explicit theoretical approach and independent sustainability evaluation component."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "table_0",
      "quote": "• Were published in a peer-review journal ... Exclusion criteria: • Were gray literature",
      "reason": "Publication status (peer-reviewed, no gray literature) is specified, but dissemination year and language restrictions are not stated in the eligibility criteria; the English-language restriction appears only in the Limitations section (text_21), not as an explicit eligibility criterion."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "table_0",
      "quote": "Did not evaluate the sustainability of an EBI or QI intervention using a defined approach",
      "reason": "Exclusion was based on whether sustainability was evaluated using a defined approach, not on outcome measurement or reporting; the distinction between outcomes not measured versus not reported does not apply to this review's eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "The two reviewers independently extracted the following variables: (1) study design, (2) evaluation type (independent versus composite), (3) sustainability definition and terms used, (4) type and name of theoretical approach, (5) purpose of approach use ...",
      "reason": "Data extraction variables suggest grouping dimensions (e.g., evaluation type, type of theoretical approach), but the groups used in each synthesis are not explicitly specified or linked to the review objectives' comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided for notable restrictions such as excluding gray literature, requiring an independent sustainability evaluation component, or restricting to healthcare settings."
    }
  ],
  "confidence": 82
}

